        "explanation": "U.P.P.C.S. (Pre) 1992\nस्वेज नहर (Suez Canal) िमस्र के स्वेज स्थलडमरूमध्य (Isthmus of\nSuez) के उत्तर से दिक्षण िदशा की ओर बनाई गई िवश्व की सबसे बड़ी\nकृित्रम नहर है। वषर् 1869 में इसकी लंबाई 164 िकमी. थी तथा वषर् 2015\nमें इसकी कुल लंबाई 193.30 िकमी. थी। भूमध्य सागर (Mediterranean\nSea) और लाल सागर (Red Sea) को जोड़ने वाली इस नहर को 1869 ई.\nमें जहाजों के आवागमन के िलए खोल िदया गया था। इसके दिक्षणी िसरे पर\nस्वेज शहर में तेवफीक बंदरगाह (Port Tewfik) (स्वेज बंदरगाह) और उत्तरी\nिसरे पर पोटर् सईद (Port Said) बंदरगाह िस्थत है। इस नहर के बन जाने से\nयूरोप और एिशया के बीच की दूरी काफी कम हो गई है, क्योंिक इसके बनने\nसे पूवर् यूरोप से एिशया और एिशया से यूरोप जाने वाले जहाजों को अफ्रीका\nमहाद्वीप का चक्कर लगाकर जाना होता था। स्वेज नहर िवश्व की सबसे\nबड़ी पोतवाहक नहर है।\n*\nस्वेज नहर के दोनों िसरों पर िस्थत पत्तन-युग्म है\n\n– पोटर् सईद तथा स्वेज\n*\nकथन (A) : स्वेज नहर बनाने से भारत की पिश्चमी देशों से दूरी कम\nहो गई है।\n\nकारण (R) : स्वेज नहर भूमध्य सागर को लाल सागर से जोड़ती है।\n\nनीचे िदए गए कूट का प्रयोग कर सही उत्तर चुिनए–\n\n– (A), (R) दोनों सही हैं और (R), (A) की व्याख्या करता है।\n*\nिनम्निलिखत में से कौन संसार की सबसे बड़ी पोतवाहक नहर है?\n\n– स्वेज नहर"
