        "explanation": "U.P. P.C.S. (Pre) 2024\nक्षोभमंडल की ऊपरी भाग में या क्षोभसीमा (Tropopause) में सामान्यत:\n5 से 9 मील (लगभग 8 िकमी. से 15 िकमी.) की ऊंचाई पर सैकड़ों िकमी.\nकी चौड़ी पट्टी में पिश्चम से पूवर् िदशा में प्रवािहत होने वाली पिरध्रुवीय प्रबल\nपवन धाराओं को जेट स्ट्रीम कहते हैं। जेट स्ट्रीम की खोज (पुिष्ट) िद्वतीय\nिवश्व युद्ध के दौरान हुई‚ परंतु वायुमंडलीय वैज्ञािनकों ने इससे पूवर् ही जेट\nस्ट्रीम के अिस्तत्व का िसद्धांत िदया था।\nजेट स्ट्रीम में पवन वेग में मौसमी पिरवतर्न होता है। ग्रीष्मकाल की तुलना में\nशीतकाल में ये अिधक प्रबल हो जाती हैं। इनमें पवन गित सामान्यत: 129\nसे 225 िकमी./घंटा होती है‚ परंतु कभी-कभी इनकी गित 443 िकमी./\nघंटा से अिधक तक हो जाती है। इस आधार पर जेट धाराओं की प्रवाह\nगित 300 से 500 िकमी./घंटा सही मानी जा सकती है। अत: (A) गलत\nहै‚ िकंतु (R) सही है।"
