        "explanation": "U.P.P.C.S. (Mains) 2004\nभूमध्यसागरीय जलवायु का आिवभार्व वायुदाब की पेिटयों के ऋतुवत\nस्थानांतरण के कारण होता है। ग्रीष्मकाल में सूयर् की उत्तरायण िस्थित\nके कारण वायुदाब की सभी पेिटयों में उत्तर की ओर िखसकाव हो जाता\nहै, िजससे इन प्रदेशों पर उपोष्ण किटबंधीय उच्च वायुदाब का िवस्तार हो\nजाता है और प्रितचक्रवातीय दशाएं तथा स्थल की ओर से चलने वाली शुष्क\nव्यापािरक हवाएं व्याप्त हो जाती हैं। ग्रीष्मकालीन हवाएं प्राय: शुष्क होती\nहैं। शीतकाल में जब सूयर् की दिक्षणायन िस्थित होती है, तो इन प्रदेशों के\nऊपर पछुआ हवाओं का िवस्तार हो जाता है, िजनके साथ मध्य अक्षांशों में\nउत्पन्न चक्रवातों का आगमन होने से वषार् होती है। पछुआ हवाएं चूंिक सागर\nके ऊपर से होकर आती हैं, अत: पिश्चमी तटीय भागों में पयार्प्त वषार् प्रदान\nकरती हैं। अत: कथन (A) और कारण (R) दोनों सत्य हैं तथा कारण (R),\nकथन (A) की सही व्याख्या है।"
