        "explanation": "रूसी-जमर्न वनस्पित िवज्ञानी तथा जलवायु िवज्ञानवेत्ता व्लािदमीर\nकोपेन ने 1884 ई. में िवश्व की जलवायु का वगीर्करण रूसी भाषा में\n‘द थमर्ल जोंस ऑफ द अथर्’ के रूप में प्रकािशत कराया, िजसे वषर्\n1918, 1931 तथा 1936 में संशोिधत एवं पिरमािजर्त िकया। कोपेन\nने वनस्पित को जलवायु का सही सूचक माना है। इसने कैण्डोल\nद्वारा 1874 ई. में प्रस्तािवत िवश्व के पांच वनस्पित मंडलों को िवश्व की\nजलवायु के िवभाजन का आधार बनाया है। कालांतर में कोपेन की भांित\nथानर्थ्वेट ने भी यह स्वीकार िकया िक वनस्पित, जलवायु की सूचक होती\nहै तथा वनस्पित पर वषार् की मात्रा तथा तापमान का पयार्प्त प्रभाव होता है,\nपरंतु वाष्पीकरण को भी ध्यान में रखा है। इसी आधार पर थानर्थ्वेट ने वषर्ण\nप्रभािवता (Precipitation effectiveness) को जलवायु प्रदेशों के सीमा\nिनधार्रण में महत्व प्रदान िकया है। जहां कोपेन ने वनस्पित को जलवायु का\nप्रत्यक्ष सूचक माना है, वहां थानर्थ्वेट ने वनस्पित को जलवायु के अप्रत्यक्ष\nतत्व के रूप में स्वीकार िकया है।\nS प्रजाितयां/जनजाितयां\n1. सूची-I को सूची-II से सुमेिलत कीिजए तथा सूिचयों के नीचे िदए\nगए कूट से सही उत्तर चुिनए –\n\nसूची-I (नृजातीय समूह)\nसूची-II (देश)\n\nA. यहूदी\n\n1. िमस्र\n\nB. टेडा\n\n2. ईरान\n\nC. बेजा\n\n3. लीिबया\n\nD. लुर"
